#!/usr/bin/env python3
"""Render final archival report and append archive-only status records."""
from __future__ import annotations
import json
from pathlib import Path
R=Path(__file__).resolve().parents[1]; inv=json.loads((R/'results/project_archive_inventory.json').read_text(encoding='utf-8'))
rows=inv['artifacts']; by={x['artifact_id']:x for x in rows}
methods=['PN-FP','EverTracer','CTCC','iSeal','SCW','LLMPrint','REEF','HuRef','AWM','ZeroPrint']
matrix=[]
for m in methods:
 for e in ['A/A2/A6','Ba','Bb/Bb2/Bb3']:
  if m=='PN-FP': c,n=({'A/A2/A6':'VERIFIED_ARCHIVED','Ba':'SAFE_WITH_PERMANENT_HISTORICAL_LIMITATION','Bb/Bb2/Bb3':'VERIFIED_ARCHIVED'}[e],'Original Ba frozen20k is permanently unavailable; reconstructed Bb parent is separately verified' if e=='Ba' else '')
  elif m=='SCW': c,n=({'A/A2/A6':'ARCHIVED_STRONGLY_VERIFIED','Ba':'SAFE_WITH_PERMANENT_HISTORICAL_LIMITATION','Bb/Bb2/Bb3':'VERIFIED_ARCHIVED'}[e],'Original Ba frozen20k is permanently unavailable; recovered-exact Bb inputs are separately verified' if e=='Ba' else '')
  elif m in ['EverTracer','CTCC','iSeal']: c,n=('ARCHIVED_STRONGLY_VERIFIED' if e=='A/A2/A6' or e=='Ba' else 'VERIFIED_ARCHIVED','CTCC slot uses completed Bb2; original Bb remains blocked' if m=='CTCC' and e=='Bb/Bb2/Bb3' else '')
  else:c,n=('NOT_APPLICABLE' if e=='A/A2/A6' else 'VERIFIED_ARCHIVED','A/A2 uses unmodified Base plus Git-safe detector package' if e=='A/A2/A6' else 'Shared Passive-5 archive')
  matrix.append((m,e,c,n))
lines=['# Project ModelScope Archive Final Report','','## A. Final archive summary','',f"The canonical inventory contains **{len(rows)}** important artifacts: 24 `VERIFIED_ARCHIVED`, 8 `ARCHIVED_STRONGLY_VERIFIED`, 0 `MISSING_ARCHIVE`, 7 `NOT_APPLICABLE`, and 2 `PERMANENTLY_UNAVAILABLE`. All recoverable critical artifacts are archived. No scientific computation or metric changed during remediation.",'','Early-model tiering is explicit: PN-FP A2 Teacher and PN-FP Ba Student are the two full-redownload/SHA/reload samples; the other eight early models passed strong remote filename/size/SHA-blob/source-manifest/Git-record verification without full redownload.','','## B. 30-experiment archive matrix','','| Method | Slot | Classification | Notes |','|---|---|---|---|']
lines += [f'| {m} | {e} | {c} | {n} |' for m,e,c,n in matrix]
lines += ['','## C. Artifact-level matrix','','| Artifact ID | Method | Experiment | Role | Repository | Classification | Evidence |','|---|---|---|---|---|---|---|']
for x in rows:lines.append(f"| `{x['artifact_id']}` | {x['method']} | {x['experiment']} | {x['role']} | `{x['modelscope_repo'] or 'N/A'}` | `{x['archive_classification']}` | `{x['evidence'] or 'durable Git record'}` |")
lines += ['','## D. Early model verification','','Full-redownload verified: PN-FP A2 Teacher and PN-FP Ba Student. Both passed per-file SHA and fresh-process reload; their temporary verification copies were deleted after durable evidence was saved.','','Strong-remote verified: EverTracer A/Ba, CTCC A/Ba, iSeal A6/Ba, and SCW A2/Ba. Every canonical file matched remote filename, size, SHA256/blob identity, historical source manifest, and Git archive record. These eight are not claimed as full-redownload verified.','','## E. PN-FP detector package','','The exact existing detector payload with canonical SHA `922d3aec3b6bbac62dcdcf617b41e08a1384e7875db77aa6c4f9a278e03a8612` is archived privately at `MakiseKurisuEasonHan/WMKD_Benchmark_pnfp_canonical_detector_keys`. The detector uses 1,024 canonical items. Independent redownload, package SHA, schema, and PRIVATE visibility passed; key content is not reproduced here.','','## F. EverTracer detector package','','The exact canonical `reference_merged` and 200-record frozen neighborhoods are private at `MakiseKurisuEasonHan/WMKD_Benchmark_evertracer_detector_dependencies`. Reference model 9/9 filename/size/SHA-blob identities match source merge manifest `bca1ea3d6f68c2ced8cb55d969e4710ef6b1f6921f5f9267c721ac06b5fa0aaf`. Neighborhood SHA `7834e3d77704951ea06501c2166e960fef2b147ced3d751a8e55f07ec7b3672b` and count 200 passed independent redownload.','','## G. SCW detector package','','The recovered-exact 1,000-record input is private at `MakiseKurisuEasonHan/WMKD_Benchmark_scw_recovered_exact_detector_input`. SHA `c60cd7d03acbd3535c5564eafe521f88179833761924953fa599237c5082a69d`, count, parse/schema, and independent redownload passed.','','## H. Permanently unavailable originals','','PN-FP original canonical Ba frozen20k and SCW original canonical Ba frozen20k were lost before archival and remain `PERMANENTLY_UNAVAILABLE`. They were not regenerated. Later reconstructed/recovered-exact Bb parents are distinct verified artifacts.','','## I. Passive NOT_APPLICABLE rationale','','LLMPrint, REEF, HuRef, AWM, and ZeroPrint A/A2 use the unmodified pinned canonical Base plus small Git-safe detector/fingerprint packages. Duplicating the Base into five ModelScope repos is unnecessary. Shared Ba and Bb3 datasets/Students remain verified private archives.','','## J. Server deletion survivability','','All recoverable models, datasets, processed20k artifacts, reconstructed parents, and external detector dependencies can be restored from GitHub plus PRIVATE ModelScope. PN-FP and SCW remain `SAFE_WITH_PERMANENT_HISTORICAL_LIMITATION` solely for the two already-lost original Ba datasets; all other methods are `SAFE`. This statement does not authorize deletion of AutoDL data.','','## K. Remaining limitations','','Eight early models use strong remote verification rather than full independent redownload. Two representative early models received full redownload/SHA/reload. PRIVATE ModelScope availability and account access remain external operational dependencies.','','## Final flags','']
for k,v in inv['flags'].items():lines.append(f'`{k} = {v}`')
(R/'docs/reproduction_reports/project_modelscope_archive_final_report.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
block='''\n\n## Project-wide ModelScope archival remediation — 2026-09-05\n\nTiered archival verification is complete: two early models passed full redownload/SHA/reload; eight passed strong remote filename/size/SHA-blob/manifest verification. Three detector dependency gaps were closed in PRIVATE ModelScope repositories. Canonical inventory: 41 artifacts = 24 verified, 8 strongly verified, 0 missing, 7 not applicable, and 2 permanently unavailable historical originals. Strict full-log index validation is 32/32 with no duplicate composite IDs, broken paths, or SHA mismatch. No scientific configuration, result, or metric changed; AutoDL canonical data was not deleted.\n'''
for name in ['PROJECT_STATUS.md','EXPERIMENT_LOG.md','CODEX_LOG.md']:
 p=R/name;t=p.read_text(encoding='utf-8')
 if '## Project-wide ModelScope archival remediation — 2026-09-05' not in t:p.write_text(t.rstrip()+block+'\n',encoding='utf-8')
p=R/'TODO.md';t=p.read_text(encoding='utf-8');todo='''\n- [x] Complete tiered verification for 10 early proactive Teacher/Ba model archives (2 full-redownload; 8 strong-remote).\n- [x] Archive and independently verify PN-FP, EverTracer, and SCW critical detector dependencies.\n- [x] Build the 41-artifact canonical archive inventory and pass strict 32/32 full-log index validation.\n- [ ] Do not delete AutoDL data without a separate explicit authorization.\n'''
if 'Complete tiered verification for 10 early proactive' not in t:p.write_text(t.rstrip()+'\n'+todo,encoding='utf-8')
print(json.dumps({'status':'PASS','report':str(R/'docs/reproduction_reports/project_modelscope_archive_final_report.md'),'matrix_rows':len(matrix),'artifact_rows':len(rows)}))
